// Command syscli reports low-level system information using
// platform-specific system calls.
package main

import (
	"fmt"
	"os"

	"github.com/example/syscli/internal/platform"
)

func main() {
	info, err := platform.Info()
	if err != nil {
		fmt.Fprintf(os.Stderr, "syscli: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("os:      %s\n", info.OS)
	fmt.Printf("release: %s\n", info.Release)
	fmt.Printf("arch:    %s\n", info.Arch)
	fmt.Printf("uptime:  %s\n", info.Uptime)
}
EOF
cat > internal/platform/platform.go <<'EOF'
// Package platform wraps OS-specific system calls behind a common API.
//
// Each supported OS has its own file selected by Go's filename-based build
// constraints (_linux.go, _darwin.go, _windows.go). Code shared by Unix-like
// systems lives in files guarded by //go:build linux || darwin.
//
// System calls go through golang.org/x/sys rather than the standard library's
// syscall package, which is frozen and doesn't get new calls or constants.
package platform

import "time"

// SystemInfo describes the host system.
type SystemInfo struct {
	OS      string
	Release string
	Arch    string
	Uptime  time.Duration
}

// Info returns information about the host system.
func Info() (SystemInfo, error) {
	return info()
}
EOF
cat > internal/platform/platform_unix.go <<'EOF'
//go:build linux || darwin

package platform

import (
	"fmt"

	"golang.org/x/sys/unix"
)

func info() (SystemInfo, error) {
	var u unix.Utsname
	if err := unix.Uname(&u); err != nil {
		return SystemInfo{}, fmt.Errorf("uname: %w", err)
	}

	up, err := uptime()
	if err != nil {
		return SystemInfo{}, err
	}

	return SystemInfo{
		OS:      unix.ByteSliceToString(u.Sysname[:]),
		Release: unix.ByteSliceToString(u.Release[:]),
		Arch:    unix.ByteSliceToString(u.Machine[:]),
		Uptime:  up,
	}, nil
}
EOF
cat > internal/platform/platform_linux.go <<'EOF'
package platform

import (
	"fmt"
	"time"

	"golang.org/x/sys/unix"
)

func uptime() (time.Duration, error) {
	var si unix.Sysinfo_t
	if err := unix.Sysinfo(&si); err != nil {
		return 0, fmt.Errorf("sysinfo: %w", err)
	}
	return time.Duration(si.Uptime) * time.Second, nil
}
EOF
cat > internal/platform/platform_darwin.go <<'EOF'
package platform

import (
	"fmt"
	"time"

	"golang.org/x/sys/unix"
)

func uptime() (time.Duration, error) {
	tv, err := unix.SysctlTimeval("kern.boottime")
	if err != nil {
		return 0, fmt.Errorf("sysctl kern.boottime: %w", err)
	}
	boot := time.Unix(tv.Sec, int64(tv.Usec)*int64(time.Microsecond))
	return time.Since(boot).Truncate(time.Second), nil
}
EOF
cat > internal/platform/platform_windows.go <<'EOF'
package platform

import (
	"fmt"
	"runtime"
	"time"

	"golang.org/x/sys/windows"
)

func info() (SystemInfo, error) {
	// RtlGetVersion reports the real OS version, unlike GetVersionEx, which
	// is subject to manifest-based compatibility shims.
	v := windows.RtlGetVersion()

	return SystemInfo{
		OS:      "Windows",
		Release: fmt.Sprintf("%d.%d.%d", v.MajorVersion, v.MinorVersion, v.BuildNumber),
		Arch:    runtime.GOARCH,
		Uptime:  time.Duration(windows.DurationSinceBoot()).Truncate(time.Second),
	}, nil
}
EOF
cat > internal/platform/platform_test.go <<'EOF'
package platform

import "testing"

func TestInfo(t *testing.T) {
	info, err := Info()
	if err != nil {
		t.Fatalf("Info() error: %v", err)
	}
	if info.OS == "" || info.Release == "" || info.Arch == "" {
		t.Errorf("Info() returned empty fields: %+v", info)
	}
	if info.Uptime <= 0 {
		t.Errorf("Info() uptime = %v, want > 0", info.Uptime)
	}
}
EOF
